style.css:
@-moz-document domain("twitch.tv") {
body, html {
        background-color: #0a0a0a;
        color: #e0e0e0;
    }

    * {
        border-color: #222;
    }

    a, .tw-link, .ScCoreLink-sc-16kq0mq-0, .tw-mg-x-05, .tw-font-size-6 {
        color: #b0b0b0;
    }

    button, [role="button"], .tw-card, .tw-block, .tw-core-button {
        background-color: #181818;
        color: #e0e0e0;
        border: 1px solid #222;
    }

    .chat-line__message, textarea {
        background-color: #121212;
        color: #ddd;
    }

    /* Cambia textos morados a gris claro */
    h2, h3, .tw-title, .tw-c-text-base, .tw-c-text-alt, .CoreText-sc-cpl358-0, .tw-font-size-5 {
        color: #c0c0c0;
    }

    /* Scrollbars */
    ::-webkit-scrollbar {
        width: 8px;
    }

    ::-webkit-scrollbar-track {
        background: #111;
    }

    ::-webkit-scrollbar-thumb {
        background: #333;
        border-radius: 4px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #555;
    }
}
